import csv
import hashlib
import json
import pathlib
import statistics
import sys

root = pathlib.Path(__file__).resolve().parent
host = sys.argv[1]
source = root / 'evidence' / host
inventory = json.loads((source / 'media-inventory.json').read_text())
exclusions = json.loads((root / 'measurement-exclusions.json').read_text())
rows = []
for path in sorted((source / 'results').glob('*/metrics.json')):
    metric = json.loads(path.read_text())
    if 'loadWallMs' not in metric:
        continue
    name = metric['name']
    if exclusions.get(name, {}).get('exclude_from_timing_summary'):
        continue
    spec = metric['spec']
    if any(rule['host'] == host and spec['config'].get('backend', '').startswith(rule['backend_prefix']) and rule['required_profile_marker'] not in name for rule in exclusions.get('rules', [])):
        continue
    warm = [r for r in metric['runs'] if not r['warmup']]
    if not metric.get('completed'):
        continue
    profiles = []
    for prompt_index, request in enumerate(spec['requests']):
        measured = [r for r in warm if r['promptIndex'] == prompt_index]
        first = next(r for r in metric['runs'] if r['promptIndex'] == prompt_index)
        profiles.append({'prompt_index': prompt_index, 'prompt': request['params']['prompt'], 'width': request['params']['width'], 'height': request['params']['height'], 'frames': request['params'].get('video_frames'), 'latency_ms': [r['wallMs'] for r in measured], 'median_ms': statistics.median(r['wallMs'] for r in measured), 'first_request_ms': first['wallMs'], 'first_output_ms': first['firstOutputMs'], 'median_first_progress_ms': statistics.median(r['firstProgressMs'] for r in measured), 'stage_medians_ms': {stage: statistics.median(r['stats'][stage] for r in measured) for stage in ['conditionerMs', 'denoiseMs', 'vaeMs', 'postProcessMs'] if all(stage in (r.get('stats') or {}) for r in measured)}})
    matching_jobs = []
    for job_path in (source / 'jobs').glob('*.json'):
        job = json.loads(job_path.read_text())
        if job.get('argv', [''])[-1].endswith(name + '.bench.json'):
            matching_jobs.append(job)
    job = max(matching_jobs, key=lambda j: j.get('started_utc', '')) if matching_jobs else {}
    if job.get('exit_code') != 0:
        continue
    memory = {'peak_process_rss_bytes': job.get('child_maxrss_bytes')}
    gpu_csv = source / 'logs' / (job.get('name', name) + '.gpu.csv')
    if gpu_csv.exists():
        samples = []
        for values in csv.reader(gpu_csv.read_text().splitlines()):
            if len(values) == 6:
                try:
                    samples.append([float(v.strip()) for v in values[2:]])
                except ValueError:
                    pass
        if samples:
            memory['peak_gpu_device_used_mib'] = max(v[0] for v in samples)
            memory['peak_power_w'] = max(v[2] for v in samples)
    amd = [s for s in job.get('samples', []) if 'amd_mem_info_gtt_used' in s]
    if amd:
        memory['sampled_peak_amd_vram_plus_gtt_bytes'] = max(s['amd_mem_info_gtt_used'] + s['amd_mem_info_vram_used'] for s in amd)
    outputs = {p: v for p, v in inventory.items() if p.startswith('results/' + name + '/')}
    rows.append({'name': name, 'addon_version': metric['addonVersion'], 'load_ms': metric['loadWallMs'], 'median_ms': statistics.median(r['wallMs'] for r in warm), 'load_plus_first_ms': metric['loadWallMs'] + metric['runs'][0]['wallMs'], 'prompts': profiles, 'memory': memory, 'config': spec['config'], 'outputs': outputs})
out = root / 'analysis'
out.mkdir(exist_ok=True)
(out / (host + '-native.json')).write_text(json.dumps(rows, indent=2))
print(json.dumps({'host': host, 'profiles': len(rows)} if '--quiet' in sys.argv else [{k: row[k] for k in ['name', 'load_ms', 'median_ms', 'load_plus_first_ms', 'memory']} for row in rows], indent=2))

import csv
import json
import pathlib
import re
import statistics
import sys

root = pathlib.Path(__file__).resolve().parent
host = sys.argv[1]
source = root / 'evidence' / host
exclusions = json.loads((root / 'measurement-exclusions.json').read_text())
jobs = [json.loads(path.read_text()) for path in (source / 'jobs').glob('*.json')]
patterns = {
    'conditioning_seconds': r'get_learned_condition completed, taking ([0-9.]+)s',
    'sampling_seconds': r'sampling completed, taking ([0-9.]+)s',
    'video_decode_seconds': r'decode_first_stage completed, taking ([0-9.]+)s',
    'audio_decode_seconds': r'decoding audio latent completed, taking ([0-9.]+)s',
    'logged_tensor_load_seconds': r'loading tensors completed, taking ([0-9.]+)s',
}
rows = []
for path in sorted((source / 'results').glob('*/metrics.json')):
    value = json.loads(path.read_text())
    if 'loadWallMs' in value or not value.get('completed'):
        continue
    name = value['name']
    if exclusions.get(name, {}).get('exclude_from_timing_summary'):
        continue
    matches = [job for job in jobs if job.get('argv', [''])[-1].endswith(name + '.bench.json')]
    if not matches:
        continue
    job = max(matches, key=lambda item: item.get('started_utc', ''))
    if job.get('exit_code') != 0:
        continue
    runs = []
    for run in value['runs']:
        if run.get('warmup', False):
            continue
        log = (path.parent / (str(run['index']) + '.log')).read_text(errors='replace')
        stages = {}
        for label, pattern in patterns.items():
            times = [float(item) for item in re.findall(pattern, log)]
            if times:
                stages[label] = sum(times)
        runs.append({**run, 'stages': stages})
    memory = {'peak_process_rss_bytes': job.get('child_maxrss_bytes')}
    gpu_path = source / 'logs' / (job['name'] + '.gpu.csv')
    if gpu_path.exists():
        samples = []
        for values in csv.reader(gpu_path.read_text().splitlines()):
            if len(values) == 6:
                try:
                    samples.append(float(values[2].strip()))
                except ValueError:
                    pass
        if samples:
            memory['sampled_peak_gpu_device_used_mib'] = max(samples)
    amd = [sample for sample in job.get('samples', []) if 'amd_mem_info_gtt_used' in sample]
    if amd:
        memory['sampled_peak_amd_vram_plus_gtt_bytes'] = max(sample['amd_mem_info_gtt_used'] + sample['amd_mem_info_vram_used'] for sample in amd)
    rows.append({'name': name, 'argv': value['spec']['argv'], 'runs': runs, 'timing_scope': value['timing_scope'],
                 'generation_median_seconds': statistics.median(run['generation_seconds'] for run in runs),
                 'process_wall_median_seconds': statistics.median(run['process_wall_seconds'] for run in runs),
                 'stage_medians_seconds': {label: statistics.median(run['stages'][label] for run in runs) for label in patterns if all(label in run['stages'] for run in runs)},
                 'memory': memory,
                 'caveat': 'OS file cache is uncontrolled. Engine stage timers can include lazy checkpoint reads; total logged tensor-load time overlaps other stages and must not be added to them. Warm-context profiles exclude the explicitly marked first invocation.'})
(root / 'analysis' / (host + '-cli.json')).write_text(json.dumps(rows, indent=2))
print(json.dumps({'host': host, 'profiles': len(rows)}))

import json
import pathlib
import statistics
import sys

root = pathlib.Path(__file__).resolve().parent
host = sys.argv[1]
source = root / 'evidence' / host
exclusions = json.loads((root / 'measurement-exclusions.json').read_text())
metrics = {}
jobs = [json.loads(path.read_text()) for path in (source / 'jobs').glob('*.json')]
for path in (source / 'results').glob('*/metrics.json'):
    value = json.loads(path.read_text())
    name = path.parent.name
    if not value.get('completed') or exclusions.get(name, {}).get('exclude_from_timing_summary'):
        continue
    matching = [job for job in jobs if job.get('argv', [''])[-1].endswith(name + '.bench.json')]
    if not matching or max(matching, key=lambda job: job.get('started_utc', '')).get('exit_code') != 0:
        continue
    if 'loadWallMs' in value and any(rule['host'] == host and value['spec']['config'].get('backend', '').startswith(rule['backend_prefix']) and rule['required_profile_marker'] not in name for rule in exclusions.get('rules', [])):
        continue
    metrics[name] = value
quality = []
for kind in ['video-quality', 'image-quality']:
    path = root / 'analysis' / (host + '-' + kind + '.json')
    if path.exists():
        quality.extend(json.loads(path.read_text()))
pairs = set()

def add(reference, candidate):
    if reference in metrics and candidate in metrics and reference != candidate:
        pairs.add((reference, candidate))

for candidate in metrics:
    if '-cli-' in candidate:
        if '-cli-warm-graphs-cuda-p1-' in candidate:
            add(candidate.replace('-warm-graphs-', '-warm-pinned-'), candidate)
        if '-isolated' in candidate:
            add(candidate.split('-isolated')[0] + '-parent', candidate)
        elif '-localops' in candidate:
            add(candidate.split('-localops')[0] + '-baseline', candidate)
        elif '-parallel-pack' in candidate:
            add(candidate.replace('parallel-pack', 'baseline'), candidate)
        elif candidate.endswith('-dispatch'):
            add(candidate.removesuffix('-dispatch') + '-baseline', candidate)
        if candidate.endswith('-global-flash'):
            add(candidate.removesuffix('-global-flash'), candidate)
            if '-localops-' in candidate:
                add(candidate.replace('-localops-', '-baseline-'), candidate)
        if candidate.endswith('-isolated-vae-flash'):
            add(candidate.removesuffix('-vae-flash'), candidate)
        if candidate.endswith('-full-temporal'):
            add(candidate.removesuffix('-full-temporal').replace('parallel-pack', 'baseline'), candidate)
        continue
    matching = [name for name in metrics if name.endswith('-baseline') and candidate.startswith(name[:-len('baseline')])]
    if matching:
        add(max(matching, key=len), candidate)
    if 'flux2' in candidate:
        for marker in ['-gemm', '-cpu-params', '-fa-off', '-commands-', '-serial', '-host-memory', '-sync-submit', '-dit-f16']:
            if marker in candidate:
                prefix = candidate.split(marker)[0]
                for suffix in ['-direct', '-direct-validation']:
                    add(prefix + suffix, candidate)
        if '-gemm-' in candidate:
            add(candidate.split('-gemm-')[0] + '-gemm', candidate)
            add(candidate.split('-gemm-')[0] + '-gemm-validation', candidate)
    if '-vae-resident-' in candidate:
        add(candidate.split('-vae-resident-')[0] + '-vae-resident', candidate)
    if '-global-flash-force-' in candidate:
        add(candidate.split('-force-')[0], candidate)
    if candidate.endswith('-dit-f16-full-temporal'):
        add(candidate.removesuffix('-full-temporal'), candidate)
    if candidate.endswith('-mmap'):
        add(candidate.removesuffix('-mmap'), candidate)
    if candidate.endswith('-rocwmma'):
        add(candidate.removesuffix('-rocwmma'), candidate)
    if candidate.endswith('-global-flash-resident'):
        add(candidate.removesuffix('-resident'), candidate)

if host == 'strix':
    add('r3-strix-ltx-vulkan-baseline-recheck-clean', 'r3-strix-ltx-vulkan-dit-f16')
    add('r3-strix-ltx-vulkan-baseline-recheck', 'r3-strix-ltx-vulkan-dit-f16')

def effect(reference, candidate):
    assert reference > 0 and candidate > 0
    return {'reference_seconds': reference, 'candidate_seconds': candidate,
            'seconds_saved': reference - candidate, 'latency_reduction_percent': 100 * (reference - candidate) / reference,
            'speedup': reference / candidate}

rows = []
for reference, candidate in sorted(pairs):
    left, right = metrics[reference], metrics[candidate]
    row = {'reference_profile': reference, 'candidate_profile': candidate}
    if 'loadWallMs' in left:
        assert 'loadWallMs' in right
        matched, left_times, right_times = [], [], []
        for li, request in enumerate(left['spec']['requests']):
            identity_keys = ['prompt', 'seed', 'width', 'height', 'video_frames', 'steps', 'sample_steps']
            matches = [ri for ri, other in enumerate(right['spec']['requests']) if all(request['params'].get(key) == other['params'].get(key) for key in identity_keys)]
            if len(matches) != 1:
                continue
            ri = matches[0]
            a = [run['wallMs'] / 1000 for run in left['runs'] if not run['warmup'] and run['promptIndex'] == li]
            b = [run['wallMs'] / 1000 for run in right['runs'] if not run['warmup'] and run['promptIndex'] == ri]
            if not a or not b:
                continue
            matched.append({'reference_prompt_index': li, 'candidate_prompt_index': ri, 'reference_runs_seconds': a, 'candidate_runs_seconds': b, **effect(statistics.median(a), statistics.median(b))})
            left_times.extend(a)
            right_times.extend(b)
        if not matched:
            continue
        row.update({'scope': 'native warm latency, matched prompt/seed/geometry', 'prompts': matched, **effect(statistics.median(left_times), statistics.median(right_times))})
        row['config_changes'] = {key: [left['spec']['config'].get(key), right['spec']['config'].get(key)] for key in sorted(left['spec']['config'].keys() | right['spec']['config'].keys()) if left['spec']['config'].get(key) != right['spec']['config'].get(key)}
    else:
        a = [run['generation_seconds'] for run in left['runs'] if not run.get('warmup', False)]
        b = [run['generation_seconds'] for run in right['runs'] if not run.get('warmup', False)]
        if any(value is None for value in a + b):
            continue
        assert left['timing_scope'] == right['timing_scope']
        row.update({'scope': left['timing_scope'], 'reference_runs_seconds': a, 'candidate_runs_seconds': b, **effect(statistics.median(a), statistics.median(b))})
    row['quality'] = [item for item in quality if item.get('reference_profile') == reference and item.get('candidate_profile') == candidate]
    rows.append(row)
(root / 'analysis' / (host + '-paired-effects.json')).write_text(json.dumps(rows, indent=2))
print(json.dumps({'host': host, 'pairs': len(rows), 'above_five_percent': [{key: row[key] for key in ['reference_profile', 'candidate_profile', 'reference_seconds', 'candidate_seconds', 'latency_reduction_percent']} for row in rows if row['latency_reduction_percent'] > 5]}))

import json
import pathlib
import statistics

root = pathlib.Path(__file__).resolve().parent
rows = []


def delta(before, after):
    assert before > 0 and after >= 0
    return {'before': before, 'after': after, 'absolute_change': after - before,
            'percent_change': 100 * (after - before) / before}


for host in ['rtx', 'mac', 'strix']:
    native = {item['name']: item for item in json.loads((root / 'analysis' / (host + '-native.json')).read_text())}
    pairs = json.loads((root / 'analysis' / (host + '-paired-effects.json')).read_text())
    for pair in pairs:
        before = native.get(pair['reference_profile'])
        after = native.get(pair['candidate_profile'])
        if before is None or after is None:
            continue
        result = {'host': host, 'reference': before['name'], 'candidate': after['name'],
                  'warm_seconds': delta(pair['reference_seconds'], pair['candidate_seconds']),
                  'load_seconds': delta(before['load_ms'] / 1000, after['load_ms'] / 1000),
                  'load_plus_first_seconds': delta(before['load_plus_first_ms'] / 1000, after['load_plus_first_ms'] / 1000),
                  'memory': {}, 'prompts': [], 'stages_seconds': {},
                  'caveat': 'Startup is a fresh model context, not a controlled cold OS-cache measurement. Process RSS and device-wide samples are different counters; do not sum them on unified-memory hardware.'}
        for key in before['memory'].keys() & after['memory'].keys():
            a, b = before['memory'][key], after['memory'][key]
            if a is not None and b is not None and a > 0:
                result['memory'][key] = delta(a, b)
        stage_values = {}
        for prompt in pair['prompts']:
            li, ri = prompt['reference_prompt_index'], prompt['candidate_prompt_index']
            left, right = before['prompts'][li], after['prompts'][ri]
            result['prompts'].append({
                'reference_prompt_index': li, 'candidate_prompt_index': ri,
                'warm_seconds': delta(prompt['reference_seconds'], prompt['candidate_seconds']),
                'reference_run_range_seconds': [min(prompt['reference_runs_seconds']), max(prompt['reference_runs_seconds'])],
                'candidate_run_range_seconds': [min(prompt['candidate_runs_seconds']), max(prompt['candidate_runs_seconds'])],
                'reference_run_count': len(prompt['reference_runs_seconds']),
                'candidate_run_count': len(prompt['candidate_runs_seconds']),
                'first_request_seconds': delta(left['first_request_ms'] / 1000, right['first_request_ms'] / 1000),
            })
            for key in left['stage_medians_ms'].keys() & right['stage_medians_ms'].keys():
                values = stage_values.setdefault(key, [[], []])
                values[0].append(left['stage_medians_ms'][key] / 1000)
                values[1].append(right['stage_medians_ms'][key] / 1000)
        for key, values in stage_values.items():
            before_stage, after_stage = statistics.median(values[0]), statistics.median(values[1])
            if before_stage > 0:
                result['stages_seconds'][key] = delta(before_stage, after_stage)
        rows.append(result)
target = root / 'analysis/profile-tradeoffs.json'
target.write_text(json.dumps(rows, indent=2))
print(json.dumps({'pairs': len(rows), 'path': str(target)}))

import json
import pathlib
import subprocess
import sys

root = pathlib.Path(__file__).resolve().parent
host = sys.argv[1]
source = root / 'evidence' / host
inventory = json.loads((source / 'media-inventory.json').read_text())
canonical = {}
for name, metadata in inventory.items():
    path = source / name
    if path.exists():
        canonical[metadata['sha256']] = path
def media(profile, prompt=0, iteration=1):
    name = f'results/{profile}/{prompt}-{iteration}-0.png'
    return canonical[inventory[name]['sha256']]
pairs = []
def add_available(reference, candidate):
    for prompt in range(3):
        if all(f'results/{profile}/{prompt}-1-0.png' in inventory for profile in [reference, candidate]):
            pairs.append((reference, candidate, prompt))

if host == 'rtx':
    for api in ['cuda', 'vulkan']:
        for prompt in range(3):
            pairs.append((f'r3-rtx-flux2-{api}-direct-validation', f'r3-rtx-flux2-{api}-gemm-validation', prompt))
        for shape in ['768x1024', '1280x1280']:
            ref = f'r3-rtx-flux2-{api}-{shape}-direct'
            candidate = f'r3-rtx-flux2-{api}-{shape}-gemm'
            if f'results/{candidate}/0-1-0.png' in inventory and f'results/{ref}/0-1-0.png' in inventory:
                pairs.append((ref, candidate, 0))
    for prompt in range(3):
        pairs.append(('r3-rtx-flux2-cuda-gemm-validation', 'r3-rtx-flux2-cuda-gemm-cpu-params', prompt))
        pairs.append(('r3-rtx-flux2-cuda-direct-validation', 'r3-rtx-flux2-cuda-gemm-cpu-params', prompt))
    for api in ['cuda', 'vulkan']:
        prefix = 'r3-rtx-flux2-f16-confirm-' + api + '-'
        for variant in ['gemm', 'gemm-dit-f16'] if api == 'cuda' else ['dit-f16']:
            add_available(prefix + 'baseline', prefix + variant)
        if api == 'cuda':
            add_available(prefix + 'gemm', prefix + 'gemm-dit-f16')
    for reference in ['r3-rtx-flux2-cuda-gemm-validation', 'r3-rtx-flux2-vulkan-direct-validation']:
        add_available(reference, reference + '-mmap')
elif host == 'strix':
    for api in ['vulkan', 'rocm']:
        ref = f'r3-strix-flux2-{api}-direct-validation'
        for variant in ['gemm-validation', 'cpu-params', 'host-memory', 'sync-submit', 'dit-f16']:
            add_available(ref, f'r3-strix-flux2-{api}-{variant}')
    add_available('r3-strix-flux2-confirm-rocm-direct', 'r3-strix-flux2-confirm-rocm-gemm')
    add_available('r3-strix-flux2-confirm-rocm-direct', 'r3-strix-flux2-confirm-vulkan-direct')
    for variant in ['force-blas', 'force-mmq']:
        add_available('r3-strix-flux2-rocm-gemm-validation', 'r3-strix-flux2-rocm-gemm-' + variant)
    add_available('r3-strix-flux2-abi128-rocm-direct', 'r3-strix-flux2-abi128-rocm-gemm')
    for variant in ['force-blas', 'force-mmq', 'cpu-params', 'dit-f16', 'rocwmma']:
        add_available('r3-strix-flux2-abi128-rocm-gemm', 'r3-strix-flux2-abi128-rocm-gemm-' + variant)
elif host == 'mac':
    for variant in ['gemm', 'cpu-params', 'fa-off', 'commands-2', 'commands-4', 'serial', 'dit-f16']:
        add_available('r3-mac-flux2-screen-metal-direct', 'r3-mac-flux2-screen-metal-' + variant)
    add_available('r3-mac-flux2-confirm-metal-direct', 'r3-mac-flux2-confirm-metal-gemm')
    for geometry in ['1024', '1280']:
        prefix = 'r3-mac-flux2-f16-confirm-' + geometry + '-metal-'
        add_available(prefix + 'baseline', prefix + 'dit-f16')
rows = []
for reference, candidate, prompt in pairs:
    r = subprocess.run([sys.executable, str(root / 'quality_images.py'), str(media(reference, prompt)), str(media(candidate, prompt))], capture_output=True, text=True, check=True)
    row = json.loads(r.stdout)
    row.update({'reference_profile': reference, 'candidate_profile': candidate, 'prompt_index': prompt})
    rows.append(row)
for path in sorted((source / 'results').glob('*flux2*cli*parallel-pack*/metrics.json')):
    spec = json.loads(path.read_text())
    candidate = path.parent.name
    reference = candidate.replace('parallel-pack', 'baseline')
    names = [f'results/{profile}/0.png' for profile in [reference, candidate]]
    if not spec.get('completed') or not all(name in inventory for name in names):
        continue
    r = subprocess.run([sys.executable, str(root / 'quality_images.py'), *[str(canonical[inventory[name]['sha256']]) for name in names]], capture_output=True, text=True, check=True)
    row = json.loads(r.stdout)
    row.update({'reference_profile': reference, 'candidate_profile': candidate, 'prompt_index': 0})
    rows.append(row)
(root / 'analysis' / (host + '-image-quality.json')).write_text(json.dumps(rows, indent=2))
print(json.dumps({'host': host, 'comparisons': len(rows)} if '--quiet' in sys.argv else [{k: r[k] for k in ['reference_profile', 'candidate_profile', 'prompt_index', 'psnr_db', 'ssim', 'max_absolute_difference_0_255']} for r in rows], indent=2))

import json
import pathlib
import subprocess
import sys

root = pathlib.Path(__file__).resolve().parent
host = sys.argv[1]
source = root / 'evidence' / host
inventory = json.loads((source / 'media-inventory.json').read_text())
canonical = {}
for name, metadata in inventory.items():
    if (source / name).exists():
        canonical[metadata['sha256']] = source / name
profiles = {path.parent.name for path in (source / 'results').glob('*/metrics.json') if json.loads(path.read_text()).get('completed')}
known_comparisons = {}
for path in (root / 'analysis').glob(host + '-video-*.json'):
    previous = json.loads(path.read_text())
    if isinstance(previous, dict) and previous.get('metrics_schema') == 2 and len(previous.get('output_file_hashes', [])) == 2:
        known_comparisons[tuple(previous['output_file_hashes'])] = previous
pairs = []
for profile in sorted(profiles):
    if 'flux2' in profile:
        continue
    if '-cli-' in profile:
        if '-cli-warm-graphs-cuda-p1-' in profile:
            pairs.append((profile.replace('-warm-graphs-', '-warm-pinned-'), profile, '0.avi', '0.avi'))
        pairs.append((profile, profile, '0.avi', '1.avi'))
        if 'parallel-pack' in profile:
            ref = profile.replace('parallel-pack', 'baseline')
        elif '-localops' in profile:
            ref = profile.split('-localops')[0] + '-baseline'
        elif profile.endswith('-dispatch'):
            ref = profile.removesuffix('-dispatch') + '-baseline'
        elif 'isolated' in profile:
            ref = profile.split('isolated')[0] + 'parent'
        else:
            ref = profile
        pairs.append((ref, profile, '0.avi', '1.avi' if ref == profile else '0.avi'))
        if profile.endswith('-global-flash'):
            base = profile.removesuffix('-global-flash').replace('parallel-pack', 'baseline')
            pairs.append((base, profile, '0.avi', '0.avi'))
        if profile.endswith('-isolated-vae-flash'):
            pairs.append((profile.removesuffix('-vae-flash'), profile, '0.avi', '0.avi'))
        if profile.endswith('-localops-global-flash'):
            pairs.append((profile.removesuffix('-global-flash'), profile, '0.avi', '0.avi'))
            pairs.append((profile.replace('-localops-', '-baseline-'), profile, '0.avi', '0.avi'))
        if profile.endswith('-full-temporal'):
            base = profile.removesuffix('-full-temporal').replace('parallel-pack', 'baseline')
            pairs.append((base, profile, '0.avi', '0.avi'))
    else:
        matching = [p for p in profiles if p.endswith('-baseline') and profile.startswith(p[:-len('baseline')])]
        if matching:
            ref = max(matching, key=len)
            spec = json.loads((source / 'results' / profile / 'metrics.json').read_text())['spec']
            for index in range(len(spec['requests'])):
                pairs.append((ref, profile, f'{index}-1-0.avi', f'{index}-2-0.avi' if ref == profile else f'{index}-1-0.avi'))
        if '-global-flash-force-' in profile:
            pairs.append((profile.split('-force-')[0], profile, '0-1-0.avi', '0-1-0.avi'))
        if profile.endswith('-dit-f16-full-temporal'):
            pairs.append((profile.removesuffix('-full-temporal'), profile, '0-1-0.avi', '0-1-0.avi'))
        if profile.endswith('-mmap'):
            pairs.append((profile.removesuffix('-mmap'), profile, '0-1-0.avi', '0-1-0.avi'))
        if profile.endswith('-rocwmma'):
            pairs.append((profile.removesuffix('-rocwmma'), profile, '0-1-0.avi', '0-1-0.avi'))
        if profile.endswith('-global-flash-resident'):
            spec = json.loads((source / 'results' / profile / 'metrics.json').read_text())['spec']
            for index in range(len(spec['requests'])):
                pairs.append((profile.removesuffix('-resident'), profile, f'{index}-1-0.avi', f'{index}-1-0.avi'))
rows = []
if host == 'strix':
    for control in ['r3-strix-ltx-vulkan-baseline-recheck-clean', 'r3-strix-ltx-vulkan-baseline-recheck']:
        if {control, 'r3-strix-ltx-vulkan-dit-f16'} <= profiles:
            pairs.append((control, 'r3-strix-ltx-vulkan-dit-f16', '0-1-0.avi', '0-1-0.avi'))
quality_only_pair = ('r3-strix-h3-full-abi128-rocm-baseline', 'r3-strix-h3-full-quality-abi128-rocm-global-flash', '0-0-0.avi', '0-0-0.avi')
if host == 'strix' and quality_only_pair[1] in profiles:
    pairs.append(quality_only_pair)
for reference, candidate, rfile, cfile in dict.fromkeys(pairs):
    names = [f'results/{reference}/{rfile}', f'results/{candidate}/{cfile}']
    quality_only = host == 'strix' and (reference, candidate, rfile, cfile) == quality_only_pair
    if (reference not in profiles and not quality_only) or not all(name in inventory for name in names):
        continue
    paths = [canonical[inventory[name]['sha256']] for name in names]
    suffix = '' if rfile in ['0.avi', '0-1-0.avi'] else '--' + rfile.removesuffix('.avi')
    cached = root / 'analysis' / (host + '-video-' + reference + '--' + candidate + suffix + '.json')
    identity = {'reference_profile': reference, 'candidate_profile': candidate, 'reference_file': rfile, 'candidate_file': cfile, 'output_file_hashes': [inventory[name]['sha256'] for name in names]}
    previous = json.loads(cached.read_text()) if cached.exists() else {}
    if previous.get('output_file_hashes') == identity['output_file_hashes'] and previous.get('metrics_schema') == 2:
        row = previous
    else:
        identical_files = known_comparisons.get(tuple(identity['output_file_hashes']))
        if identical_files is not None:
            row = dict(identical_files)
        else:
            result = subprocess.run([sys.executable, str(root / 'quality_video.py'), *map(str, paths)], capture_output=True, text=True, check=True)
            row = json.loads(result.stdout)
        row.update(identity)
        cached.write_text(json.dumps(row, indent=2))
        known_comparisons[tuple(identity['output_file_hashes'])] = row
    if quality_only:
        row['quality_scope'] = 'Full-size output comparison only. The reference timing profile was interrupted by external contention and is excluded from latency results.'
        cached.write_text(json.dumps(row, indent=2))
    rows.append(row)
(root / 'analysis' / (host + '-video-quality.json')).write_text(json.dumps(rows, indent=2))
print(json.dumps({'host': host, 'comparisons': len(rows)} if '--quiet' in sys.argv else [{k: row.get(k) for k in ['reference_profile', 'candidate_profile', 'reference_file', 'video_psnr_db', 'video_ssim', 'audio_rmse_float']} for row in rows], indent=2))

import json
import pathlib

root = pathlib.Path(__file__).resolve().parent
reviews = json.loads((root / 'visual-review.json').read_text())['comparisons']
rows = []
for host in ['rtx', 'mac', 'strix']:
    quality = json.loads((root / 'analysis' / (host + '-video-quality.json')).read_text())
    accepted = []
    for review in reviews:
        if not any(term in review['finding'].lower() for term in ['no visible', 'no obvious visible', 'no obvious appearance']):
            continue
        for item in quality:
            if item['reference_profile'] == review['reference'] and item['candidate_profile'] == review['candidate'] and item.get('audio_rmse_float') == 0:
                accepted.append((frozenset(item['decoded_video_sha256']), review))
    for item in quality:
        if item['reference_profile'] == item['candidate_profile'] or item.get('audio_rmse_float') != 0:
            continue
        hashes = frozenset(item['decoded_video_sha256'])
        if len(hashes) == 1:
            continue
        matched = next((review for pair, review in accepted if pair == hashes), None)
        if matched:
            rows.append({'host': host, 'reference_profile': item['reference_profile'], 'candidate_profile': item['candidate_profile'],
                         'reference_file': item['reference_file'], 'candidate_file': item['candidate_file'],
                         'decoded_video_sha256': item['decoded_video_sha256'],
                         'review_source': {key: matched[key] for key in ['reference', 'candidate', 'inspection']},
                         'meaning': 'The full decoded baseline/candidate videos match a previously inspected pair by SHA256. This transfers the sampled visual inspection, not a new blinded or all-prompt quality guarantee.'})
(root / 'analysis/visual-equivalence.json').write_text(json.dumps(rows, indent=2))
print(json.dumps({'reviewed_nonexact_video_pairs_by_hash': len(rows)}))

